<?php require 'header.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT o.*,c.full_name,c.phone,c.whatsapp,c.email,c.address FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=?');$s->execute([$id]);$o=$s->fetch();if(!$o){http_response_code(404);echo '<p>Order not found.</p>';require 'footer.php';exit;}$s=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();$s=db()->prepare('SELECT h.*,a.full_name admin_name FROM order_status_history h LEFT JOIN admins a ON a.id=h.changed_by_admin WHERE h.order_id=? ORDER BY h.created_at DESC');$s->execute([$id]);$history=$s->fetchAll();?><div class="admin-title"><p><?=e($o['order_number'])?></p><h2>Order details</h2><a href="edit-order.php?id=<?=$id?>">Edit order</a></div><section class="admin-panel"><h3><?=e($o['full_name'])?></h3><p><?=e($o['email'])?> · <?=e($o['phone'])?> · <?=e($o['whatsapp'])?></p><p><?=e($o['address'])?></p><p><?=money($o['total'])?> · <?=e($o['payment_method'])?> · <?=e($o['status'])?></p><table><thead><tr><th>Product</th><th>Unit price</th><th>Quantity</th><th>Line total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=money($i['unit_price'])?></td><td><?=$i['quantity']?></td><td><?=money($i['unit_price']*$i['quantity'])?></td></tr><?php endforeach?></tbody></table><h3>Status history</h3><?php foreach($history as $h):?><p><?=e($h['created_at'])?> · <?=e($h['old_status']??'Created')?> → <?=e($h['new_status'])?><?= $h['admin_name']?' · '.e($h['admin_name']):'' ?></p><?php endforeach?><a href="manage-orders.php">Back to orders</a></section><?php require 'footer.php';
